'use client'

import { useState } from 'react'
import { STORIES } from '@/lib/stories-data'
import { StoryViewer } from './story-viewer'

export function StoriesCarousel() {
  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null)
  const [viewerKey, setViewerKey] = useState(0)

  const selectedStory = selectedStoryIndex !== null ? STORIES[selectedStoryIndex] : null

  const handleCloseStory = () => {
    setSelectedStoryIndex(null)
    setViewerKey(prev => prev + 1)
  }

  const handleNextStory = () => {
    if (selectedStoryIndex !== null && selectedStoryIndex < STORIES.length - 1) {
      setSelectedStoryIndex(selectedStoryIndex + 1)
      setViewerKey(prev => prev + 1)
    } else {
      handleCloseStory()
    }
  }

  const handlePrevStory = () => {
    if (selectedStoryIndex !== null && selectedStoryIndex > 0) {
      setSelectedStoryIndex(selectedStoryIndex - 1)
      setViewerKey(prev => prev + 1)
    }
  }

  return (
    <>
      {/* Stories carousel */}
      <div className="flex gap-3 overflow-x-auto pb-4 scrollbar-hide">
        {STORIES.map((story, index) => (
          <button
            key={story.id}
            onClick={() => {
              setSelectedStoryIndex(index)
              setViewerKey(prev => prev + 1)
            }}
            className="flex-shrink-0 group relative"
          >
            {/* Story thumbnail */}
            <div className="w-20 h-28 rounded-xl overflow-hidden border-2 border-primary/40 hover:border-primary transition-all duration-300 relative">
              <img
                src={story.thumbnail}
                alt={story.title}
                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
              />
              {/* Gradient overlay */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
            </div>

            {/* Story title */}
            <p className="text-xs text-white mt-2 text-center font-semibold truncate w-20">
              {story.title}
            </p>

            {/* Add indicator dot */}
            <div className="absolute top-1 right-1 w-2 h-2 bg-primary rounded-full opacity-0 group-hover:opacity-100 transition-opacity" />
          </button>
        ))}
      </div>

      {/* Story Viewer Modal */}
      {selectedStory && (
        <StoryViewer
          key={viewerKey}
          story={selectedStory}
          onClose={handleCloseStory}
          onNext={handleNextStory}
          onPrev={handlePrevStory}
        />
      )}
    </>
  )
}
